	Dictionary<int, Type> IfsGraphLookupType.Types => lookup;

	public int CurIndex
	{
		get
		{
			return curIndex;
		}
		set
		{
			curIndex = value;
		}
	}

	private void Awake()
	{
		InitTypes();
	}

	public static void InitTypes()
	{
		if (fsSerializationContext.mLookupType == null)
		{
			GameObject gameObject = GameObject.Find("IfsGraphLookupType");
			if (gameObject != null)
			{
				fsSerializationContext.mLookupType = U3DUtil.Get<fsGraphLookupType>(gameObject);
				return;
			}
			gameObject = new GameObject("IfsGraphLookupType", typeof(fsGraphLookupType));
			fsSerializationContext.mLookupType = gameObject.GetComponent<IfsGraphLookupType>();
		}
	}
}
